// Function to check file integrity
bool CheckFileIntegrity(string filePath) {
    // Calculate file hash using Cosmic DLL
    string calculatedHash = CosmicDLL::HashFile(filePath, hashAlgorithm);

    // Compare hash with known good hash
    bool isIntegrityValid = compareHash(calculatedHash, knownGoodHash);

    // Verify digital signature if available
